class GPTEditorial50SourceTests(unittest.TestCase):
    def test_exact_50_independent_original_cases_and_actual_board_groups(self):
        for n,(board,ev_sha,board_sha,grade,score,day,hour) in LOCKS.items():
            ju=board.split('-')[1]
            path=BOARD/"阳遁"/(ju+"局")/hour/"父亲"/(f"case-{n:06d}-jieqi-a.v9.json")
            with self.subTest(case=n):
                self.assertTrue(path.is_file(),str(path))
                d=json.loads(path.read_text(encoding="utf-8"))
                l=d['fact_lock'];s=d['source_context'];e=d['editorial']
                self.assertEqual(d['physical_chart']['key'],board)
                self.assertEqual(d['physical_chart']['ju'],int(ju))
                self.assertEqual(d['physical_chart']['hour_ganzhi'],hour)
                self.assertEqual((s['year'],s['month'],s['day'],s['hour']),('甲子','丙寅',day,hour))
                self.assertEqual((l['grade'],l['score']),(grade,score))
                self.assertEqual((l['original_evidence_sha256'],l['physical_board_sha256']),(ev_sha,board_sha))
                self.assertEqual((l['patient_symbol'],l['carrier_stem']),('甲','戊'))
                self.assertEqual(s['solar_term_branch'],'a')
                self.assertEqual(s['natal_mode'],'none')
                self.assertEqual(e['status'],'draft')
                self.assertIs(e['human_approved'],False)
                self.assertTrue(e.get('reviewer') is None)
                self.assertEqual(len(e['front_screen']['text'].split('\n\n')),6)
                self.assertEqual(len(e['professional_sections']),10)
                self.assertEqual(e['front_screen']['title'].split('：')[0],grade)
    def test_50_not_automatically_approved(self):
        self.assertEqual(len(LOCKS),50)
        self.assertEqual(sum(k<=60 for k in LOCKS),20)
        self.assertEqual(sum(k>60 for k in LOCKS),30)
if __name__=='__main__':unittest.main()